          <IonToolbar className="ion-padding">
            <IonButton expand="block" onClick={handleSave} disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : <><IonIcon icon={saveOutline} slot="start" /> Guardar</>}
            </IonButton>
          </IonToolbar>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar eliminación'}
          message={'¿Estás seguro de que quieres eliminar este item del catálogo de recompensas?'}
          buttons={[
            { text: 'Cancelar', role: 'cancel', handler: () => setShowDeleteAlert(false) },
            { text: 'Eliminar', handler: handleConfirmDelete, cssClass: 'danger' }
          ]}
        />

        <IonToast
          isOpen={!!toastMessage}
          message={toastMessage}
          duration={3000}
          onDidDismiss={() => setToastMessage('')}
          color={toastMessage.toLowerCase().includes('error') ? 'danger' : 'success'}
        />
      </IonContent>
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
